repo_files.interpolator.py:
"""Resolves environment variable expressions in configuration strings."""

import re
from typing import Any, Dict

PATTERN = re.compile(r"\$\{([A-Za-z0-9_]+)(?::-([^}]*))?\}")


class EnvInterpolator:
    def __init__(self, env: Dict[str, str]):
        self.env = env

    def interpolate_string(self, text: str) -> str:
        def replace(match: re.Match) -> str:
            var_name = match.group(1)
            default_val = match.group(2) if match.group(2) is not None else ""
            # BUG: Returns empty string when env var is missing and default is given as empty string vs None
            if var_name in self.env:
                return self.env[var_name]
            if match.group(2) is not None:
                return default_val
            return match.group(0)  # Unresolved literal

        # BUG: Only executes a single pass, failing nested or chained expressions like ${A:-${B}}
        return PATTERN.sub(replace, text)

    def interpolate_tree(self, obj: Any) -> Any:
        if isinstance(obj, str):
            return self.interpolate_string(obj)
        if isinstance(obj, dict):
            return {k: self.interpolate_tree(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [self.interpolate_tree(elem) for elem in obj]
        return obj

repo_files.merger.py:
"""Deep merging of nested configurations with conflict strategies."""

from typing import Any, Dict


def deep_merge(target: Dict[str, Any], source: Dict[str, Any]) -> Dict[str, Any]:
    result = dict(target)
    for k, v in source.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = deep_merge(result[k], v)
        else:
            result[k] = v
    return result

repo_files.provider.py:
"""Unified configuration provider combining interpolation and merging."""

from typing import Any, Dict
from interpolator import EnvInterpolator
from merger import deep_merge


class ConfigProvider:
    def __init__(self, env: Dict[str, str]):
        self.interpolator = EnvInterpolator(env)

    def compose(self, base_cfg: Dict[str, Any], overrides: Dict[str, Any]) -> Dict[str, Any]:
        merged = deep_merge(base_cfg, overrides)
        return self.interpolator.interpolate_tree(merged)

tests.test_config_interpolation.py:
from provider import ConfigProvider


def test_basic_env_substitution():
    env = {"DB_HOST": "postgres.internal", "DB_PORT": "5432"}
    provider = ConfigProvider(env)
    base = {"db": {"host": "${DB_HOST}", "port": "${DB_PORT}"}}
    cfg = provider.compose(base, {})
    assert cfg["db"]["host"] == "postgres.internal"
    assert cfg["db"]["port"] == "5432"


def test_default_fallback_when_env_missing():
    env = {}
    provider = ConfigProvider(env)
    base = {"api": {"timeout": "${API_TIMEOUT:-30}", "prefix": "${API_PREFIX:-/v1}"}}
    cfg = provider.compose(base, {})
    assert cfg["api"]["timeout"] == "30"
    assert cfg["api"]["prefix"] == "/v1"


def test_nested_array_and_dict_interpolation():
    env = {"NODE_1": "10.0.0.1", "NODE_2": "10.0.0.2"}
    provider = ConfigProvider(env)
    base = {"cluster": {"nodes": ["${NODE_1}", "${NODE_2}", "${NODE_3:-10.0.0.3}"]}}
    cfg = provider.compose(base, {})
    assert cfg["cluster"]["nodes"] == ["10.0.0.1", "10.0.0.2", "10.0.0.3"]


def test_override_deep_merge_with_interpolation():
    env = {"LOG_LEVEL": "DEBUG"}
    provider = ConfigProvider(env)
    base = {"service": {"name": "auth", "log": {"level": "INFO", "format": "text"}}}
    overrides = {"service": {"log": {"level": "${LOG_LEVEL}"}}}
    cfg = provider.compose(base, overrides)
    assert cfg["service"]["name"] == "auth"
    assert cfg["service"]["log"]["level"] == "DEBUG"
    assert cfg["service"]["log"]["format"] == "text"


def test_unresolved_env_without_default_remains_literal():
    env = {}
    provider = ConfigProvider(env)
    base = {"custom": {"raw_template": "${UNSET_VAR}"}}
    cfg = provider.compose(base, {})
    assert cfg["custom"]["raw_template"] == "${UNSET_VAR}"


def test_chained_nested_expression_resolution():
    env = {"SECONDARY": "backup.server"}
    provider = ConfigProvider(env)
    base = {"host": "${PRIMARY:-${SECONDARY}}"}
    cfg = provider.compose(base, {})
    assert cfg["host"] == "backup.server"

reference_fix.interpolator.py:
"""Resolves environment variable expressions in configuration strings."""

import re
from typing import Any, Dict

PATTERN = re.compile(r"\$\{([A-Za-z0-9_]+)(?::-([^}]*))?\}")


class EnvInterpolator:
    def __init__(self, env: Dict[str, str]):
        self.env = env

    def interpolate_string(self, text: str) -> str:
        def replace_single(match: re.Match) -> str:
            var_name = match.group(1)
            default_val = match.group(2)
            if var_name in self.env:
                return self.env[var_name]
            if default_val is not None:
                return default_val
            return match.group(0)

        prev = text
        for _ in range(5):
            nxt = PATTERN.sub(replace_single, prev)
            if nxt == prev:
                break
            prev = nxt
        return prev

    def interpolate_tree(self, obj: Any) -> Any:
        if isinstance(obj, str):
            return self.interpolate_string(obj)
        if isinstance(obj, dict):
            return {k: self.interpolate_tree(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [self.interpolate_tree(elem) for elem in obj]
        return obj
